WITH unpacked AS (SELECT id, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT CASE WHEN avg_tier_price >= 36 THEN 'LARGE' ELSE 'SMALL' END AS avg_tier_price_tier, COUNT(*) AS cnt, COUNT(*) AS event_count, ROUND(AVG(avg_tier_price), 2) AS avg_avg_tier_price, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(avg_tier_price, 0.95) AS avg_tier_price_p95, APPROX_PERCENTILE(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles FROM unpacked GROUP BY 1 ORDER BY event_count DESC NULLS FIRST
